import React from 'react';
import PropTypes from 'prop-types';
import classnames from 'classnames';
import { settings } from 'carbon-components';

const { prefix } = settings;

const ProgressBar = ({ value, max, label }) => {
  const percentage = (value / max) * 100;
  return (
    <div className={`${prefix}--progress-bar`} role="progressbar" aria-valuenow={value} aria-valuemin="0" aria-valuemax={max}>
      <div className={`${prefix}--progress-bar__bg`}>
        <div className={`${prefix}--progress-bar__fill`} style={{ width: `${percentage}%` }} />
      </div>
      {label && (
        <span className={`${prefix}--progress-bar__label`}>
          {`${percentage}% - ${label}`}
        </span>
      )}
    </div>
  );
};

ProgressBar.propTypes = {
  value: PropTypes.number.isRequired,
  max: PropTypes.number.isRequired,
  label: PropTypes.string,
};

export default ProgressBar;
```

